let favorites=[];try{favorites=JSON.parse(localStorage.getItem('ordinals-studio-favorites')||'[]');if(!Array.isArray(favorites))favorites=[]}catch{}
function render(){const start=performance.now();generate();const [w,h]=dims,cols=drawingPalette();$('art').setAttribute('viewBox',`0 0 ${w} ${h}`);$('art').innerHTML=paths.map(p=>`<path d="${dOf(p.points)}" fill="none" stroke="${cols[p.layer]}" stroke-width="${p.weight??s.weight}" stroke-linecap="round" stroke-linejoin="round"/>`).join('')+($('guides').checked?`<rect x="${s.margin}" y="${s.margin}" width="${w-2*s.margin}" height="${h-2*s.margin}" fill="none" stroke="#9b9b91" stroke-width=".15" stroke-dasharray="1 2" opacity=".45"/>`:'');$('paperWrap').style.aspectRatio=w+'/'+h;$('paperWrap').style.width=`min(100%, calc((100dvh - 355px) * ${w/h}))`;$('paperWrap').style.background={white:'#f2f0e9',kraft:'#c4a579',black:'#191e21'}[s.paper];$('dimensions').textContent=`${w} × ${h} MM · MARGE ${s.margin} MM`;$('status').textContent='SEED '+s.seed+(playing?' · ANIMATION':' · FIGÉE');$('caption').textContent=names[s.engine]+' — '+s.seed;$('stats').textContent=paths.length.toLocaleString('fr')+' TRACÉS / '+Math.round(performance.now()-start)+' MS';$('artTitle').textContent=s.poster.enabled?'La lettre devient paysage.':titles[s.engine];$('paperWrap').classList.toggle('is-poster',s.poster.enabled);updatePosterStatus();updateTypographyStatus();$('index').textContent=String(study).padStart(3,'0')}
function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(render)}
function controls(){normalizeState();document.querySelectorAll('[data-engine]').forEach(b=>b.classList.toggle('active',b.dataset.engine===s.engine));let html=geometryControlsHTML();if(s.engine==='flow')html='<label>Champ<select id="mode"><option value="vortex">Vortex</option><option value="gravity">Attraction / répulsion</option></select></label>';if(s.engine==='cell')html='<label>Construction<select id="mode"><option value="voronoi">Cellules de Voronoï</option><option value="delaunay">Triangulation de Delaunay</option></select></label>';if(s.engine==='op')html='<label>Motif<select id="mode"><option value="wave">Vagues déformées</option><option value="rings">Anneaux concentriques</option></select></label>';if(s.engine==='type')html=typeControlsHTML();
html+=specs[s.engine].map(([key,label,min,max,step])=>`<label>${label}<input class="param-number" aria-label="${label} — valeur" type="number" data-number="${key}" min="${min}" max="${max}" step="${step}" value="${s.params[key]}"><input type="range" data-param="${key}" min="${min}" max="${max}" step="${step}" aria-label="${label}" value="${s.params[key]}"></label>`).join('');$('engineControls').innerHTML=html;if($('mode')){$('mode').value=s.params.field||s.params.mode;$('mode').onchange=e=>{s.params[s.engine==='flow'?'field':'mode']=e.target.value;schedule()}}if($('words')){$('words').value=s.params.text;$('words').oninput=e=>{s.params.text=e.target.value;schedule()}}document.querySelectorAll('[data-param]').forEach(el=>el.oninput=()=>{s.params[el.dataset.param]=+el.value;document.querySelector('[data-number="'+el.dataset.param+'"]').value=el.value;schedule()});document.querySelectorAll('[data-number]').forEach(el=>el.onchange=()=>{let v=Number(el.value);if(!Number.isFinite(v))return;v=Math.max(+el.min,Math.min(+el.max,v));v=+((+el.min)+Math.round((v-(+el.min))/(+el.step))*(+el.step)).toFixed(5);s.params[el.dataset.number]=v;el.value=v;document.querySelector('[data-param="'+el.dataset.number+'"]').value=v;schedule()});$('tip').textContent={flow:'Cliquez sur le papier pour placer jusqu’à 4 points de force. Double-cliquez pour les effacer. Une force négative inverse le mouvement.',cell:'Le retrait isole les cellules. La dispersion les éclate selon un masque de bruit déterministe.',type:'Les polices sont tracées en contours vectoriels. Corps et nombre de lignes sont indépendants ; les marges coupent les débordements.',op:'Des lignes simples. Des interférences complexes. Animez pour explorer, puis figez votre composition.',super:'La superformule de Gielis : symétrie, tension et courbure. Décroissance et torsion composent les contours. Symétrie paire pour des courbes fermées.',iso:'Cubes multi-échelles : la subdivision mélange petits et grands volumes. À 0 %, gros cubes ; à 100 %, tous petits. L’occupation creuse la structure. Remplir la zone agrandit et coupe aux marges ; les creux restent visibles. La densité de grille conserve les proportions du relief.'}[s.engine];sync();bindTypeControls();bindGeometryControls();posterControls()}
function sync(){for(let key of['seed','format','margin','paper','palette','weight'])$(key).value=s[key];$('marginVal').textContent=s.margin+' mm';$('weightVal').textContent=s.weight.toFixed(2)+' mm';$('swatches').innerHTML=palette().map((c,i)=>`<span style="background:${c}" title="Plume ${i+1}: ${c}">${i+1}</span>`).join('')}
function pause(){playing=false}
function toast(msg){$('toast').textContent=msg;document.body.classList.add('toast');clearTimeout(toast.timer);toast.timer=setTimeout(()=>document.body.classList.remove('toast'),3200)}
for(let b of document.querySelectorAll('[data-engine]'))b.onclick=()=>{pause();s.engine=b.dataset.engine;s.params={...defaults[s.engine]};phase=0;s.points=[];controls();render()};for(let b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.tab').forEach(x=>x.hidden=x.id!==b.dataset.tab)};
for(let key of['seed','format','margin','paper','palette','weight'])$(key).oninput=()=>{let val=$(key).value;if(['seed','margin','weight'].includes(key)){val=Number(val);if(!Number.isFinite(val))return;if(key==='seed')val=Math.max(1,Math.min(999999,Math.round(val)))}s[key]=val;sync();schedule()};$('guides').onchange=schedule;
$('newSeed').onclick=()=>{if(locked)return toast('Seed verrouillée. Cliquez sur le losange pour la libérer.');s.seed=1+Math.floor(Math.random()*999998);phase=0;sync();schedule()};$('lock').onclick=()=>{locked=!locked;$('lock').setAttribute('aria-pressed',locked);$('lock').textContent=locked?'◆':'◇'};
$('random').onclick=()=>{pause();phase=0;study++;if(!locked)s.seed=1+Math.floor(Math.random()*999998);const r=random(s.seed+study*71);if(s.engine==='flow')Object.assign(s.params,{frequency:+(.7+r()*3.2).toFixed(1),amplitude:+(.7+r()*2.4).toFixed(1),density:100+Math.floor(r()*140),length:150+Math.floor(r()*180),force:+(.5+r()*1.8).toFixed(1)});if(s.engine==='cell')Object.assign(s.params,{density:35+Math.floor(r()*100),offset:3+Math.floor(r()*22),explode:Math.floor(r()*24)});if(s.engine==='type')Object.assign(s.params,{density:8+Math.floor(r()*15),amplitude:Math.floor(r()*23),scale:+(r()*2).toFixed(1)});if(s.engine==='op')Object.assign(s.params,{density:55+Math.floor(r()*90),amplitude:10+Math.floor(r()*26),frequency:Math.floor(2+r()*5)});randomizeGeometry(r);s.points=[];controls();render()};
$('reset').onclick=()=>{pause();phase=0;s.points=[];s.params={...defaults[s.engine]};controls();render()};$('play').onclick=()=>previewBlock(currentBlock.height+1);
$('focus').onclick=()=>document.body.classList.toggle('focus');$('togglePanel').onclick=()=>{if(innerWidth<=650)document.body.classList.toggle('panel-mobile');else document.body.classList.toggle('focus')};document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName))return;if(e.key.toLowerCase()==='r')$('random').click();if(e.code==='Space'){e.preventDefault();$('play').click()}if(e.key.toLowerCase()==='f'){$('focus').click()}if(e.key==='Escape'){document.body.classList.remove('focus','panel-mobile')}});
$('art').onclick=e=>{if(s.engine!=='flow'||s.poster.enabled)return;const rect=$('art').getBoundingClientRect();if(s.points.length>=4)s.points.shift();s.points.push({x:(e.clientX-rect.left)/rect.width*dims[0],y:(e.clientY-rect.top)/rect.height*dims[1]});schedule();toast(s.points.length+' point(s) de force placé(s)')};$('art').ondblclick=()=>{s.points=[];schedule();toast('Points de force effacés')};
function showFavs(){$('favCount').textContent=favorites.length;$('favorites').replaceChildren();favorites.forEach((f,i)=>{let row=document.createElement('div');row.className='fav';let b=document.createElement('button');b.textContent=(f.state.poster?.enabled?'AFFICHE · ':'')+names[f.state.engine]+' / '+f.state.seed;b.onclick=()=>{pause();s=structuredClone(f.state);normalizeState();phase=f.phase||0;controls();render();toast('Exploration restaurée')};let d=document.createElement('button');d.textContent='×';d.title='Supprimer ce favori';d.onclick=()=>{favorites.splice(i,1);persist();showFavs()};row.append(b,d);$('favorites').append(row)})}
function persist(){try{localStorage.setItem('ordinals-studio-favorites',JSON.stringify(favorites));return true}catch{toast('Stockage indisponible : favori conservé pour cette session.');return false}}$('save').onclick=()=>{if(favorites.length>=20)return toast('20 favoris maximum. Supprimez-en un pour faire de la place.');favorites.unshift({state:structuredClone(s),phase});const ok=persist();showFavs();if(ok)toast('Exploration enregistrée dans ce navigateur')};
function dist(a,b){return Math.hypot(a[0]-b[0],a[1]-b[1])}function clean(list){let seen=new Set,out=[];for(let p of list){let part=[];for(let i=1;i<p.points.length;i++){let a=p.points[i-1],b=p.points[i];if(dist(a,b)<.005)continue;let ka=a.map(v=>v.toFixed(3)).join(','),kb=b.map(v=>v.toFixed(3)).join(','),key=p.layer+':'+(p.weight??s.weight)+':'+[ka,kb].sort().join('|');if(seen.has(key)){if(part.length>1)out.push({...p,points:part});part=[];continue}seen.add(key);if(!part.length)part.push(a);part.push(b)}if(part.length>1)out.push({...p,points:part})}return out}
function ordered(list){if(list.length>1800){const buckets=new Map;for(const p of list){const a=p.points[0],x=Math.floor(a[0]/12),y=Math.floor(a[1]/12),key=x+','+y;if(!buckets.has(key))buckets.set(key,{x,y,paths:[]});buckets.get(key).paths.push(p)}return [...buckets.values()].sort((a,b)=>a.y-b.y||((a.y%2?-1:1)*(a.x-b.x))).flatMap(b=>b.paths.length===list.length?b.paths:ordered(b.paths))}let pending=list.map(p=>({...p,points:[...p.points]})),out=[],cursor=[0,0];while(pending.length){let idx=0,rev=false,best=Infinity;for(let i=0;i<pending.length;i++){let pts=pending[i].points,a=dist(cursor,pts[0]),b=dist(cursor,pts.at(-1));if(a<best){idx=i;rev=false;best=a}if(b<best){idx=i;rev=true;best=b}}let p=pending.splice(idx,1)[0];if(rev)p.points.reverse();out.push(p);cursor=p.points.at(-1)}return out}
function svgExport(){let list=$('dedupe').checked?clean(paths):paths,cols=drawingPalette(),meta=JSON.stringify({application:'ORDINALS Studio',version:4,state:s,phase}).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');let content=cols.map((color,i)=>{let group=list.filter(p=>p.layer===i);if($('optimize').checked)group=ordered(group);return `<g id="pen-${i+1}" inkscape:groupmode="layer" inkscape:label="${i+1} - ${color}" fill="none" stroke="${color}" stroke-width="${s.weight}" stroke-linecap="round" stroke-linejoin="round">${group.map(p=>`<path d="${dOf(p.points)}" stroke-width="${p.weight??s.weight}"/>`).join('')}</g>`}).join('');return `<?xml version="1.0" encoding="UTF-8"?><svg xmlns="${NS}" xmlns:inkscape="http://www.inkscape.org/namespaces/inkscape" width="${dims[0]}mm" height="${dims[1]}mm" viewBox="0 0 ${dims.join(' ')}"><metadata>${meta}</metadata>${content}</svg>`}
controls();showFavs();bindPosterUI();initBitcoin();render();
